    out_path = os.path.join(commerce_dir, "scripts", "branch_b", "day41_dmkt_data.json")
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(day41_data, f, indent=2)
    print(f"Successfully generated Day 41 data at {out_path}")
    total_words = 0
    for p in day41_data["parts"]:
        w = len(" ".join(p["say"]).split())
        total_words += w
        print(f"  Part {p['part']}: {p['title']} -> {w} words (Check ans: {p['check']['answer']}, idx: {p['check']['answerIndex']})")
    print(f"Total Day 41 say words: {total_words}")
